// Monsters
// One entry per monster. Rare and Epic versions are their own entries.
//
//   { name: "Rare Potbelly", rarity: "Rare", class: "Natural", elements: ["Plant"],
//     islands: [
//       { island: "Plant Island", how: "Breed", combo: ["Any Plant Triple", "Any Plant Triple"], time: "6h" },
//       { island: "Gold Island", how: "Teleport" },
//     ] },
//
// MONSTER FIELDS
//   name      exactly as shown in game. Rare/Epic versions start with "Rare " / "Epic ".
//   rarity    "Common" | "Rare" | "Epic"
//   class     "Natural" | "Fire" | "Magical" | "Ethereal" | "Mythical" | "Seasonal" | "Legendary"
//             "Supernatural" | "Paironormal" | "Primordial" | "Celestial" | "Dipster" | "Titansoul"
//   elements  list of element names (must match images/elements/<name>.png)
//   img       optional - only if the portrait file doesn't follow the normal rule:
//             "<name without Rare/Epic/Adult>[ - rare| - epic| - adult].png", lowercase, ' becomes _
//
// ISLAND ENTRY FIELDS (one per island the monster can live on)
//   island    must match a name in islands.js
//   how       how you get it on that island - one of:
//               "Breed"       breed it there; needs combo
//               "Teleport"    teleport it in; may also have combo + time if it can be re-bred there
//               "Zap"         zap it (Wublin / Amber / Celestial); needs eggs, may have limit
//               "Purchase"    buy it; put the price in cost
//               "Evolve"      Amber Island crucible
//               "Harmonize"   Islets
//               "Synthesize"  Ethereal Workshop; ingredients in uses
//               "Fuze"        Minor Paironormal Carnival; ingredients in uses
//               "Dig"         won from Dipster Digs
//   combo     two parents, e.g. ["Potbelly", "Noggin"]. Each is a monster name or a wildcard (below).
//   uses      ingredient list for Synthesize / Fuze (free text)
//   time      breeding / incubation time, e.g. "8h", "1d 6h", "2d 12h 30m"
//   enhanced  optional - ONLY when the enhanced time is not 75% of time (it's calculated otherwise)
//   fail      the time if it fails, for Synthesize / Fuze / Evolve (shown instead of an enhanced time)
//   cost      optional price text, e.g. "300 Relics", "15,000 Starpower"
//   withVessel  optional - true if it can only be bought here while its vessel is available (fire expansion monsters)
//   limit     optional zap deadline, e.g. "End of Month", "10 Days" (leave out = no time limit)
//   eggs      zap requirements: [["Potbelly", 10], ["Any Rare Air Double", 2], ...]
//   note      optional free text shown as-is
//
// WILDCARDS (usable in combo and eggs)
//   "Any Monster"            "Any Triple"              "Any <Element> Triple"  e.g. "Any Plant Triple"
//   "Any Single Ethereal"    "Any Single Mythical"     "Any Mythical"
//   "Any Rare <Element> Double|Triple|Quad"  e.g. "Any Rare Air Triple"
//   "Any Rare Wublin"
//
// After editing, run:  python tools/check_data.py   (catches typos and missing images)

